<template><div class="page"><a-button type="link" @click="$router.push('/membership/points')">← 返回积分中心</a-button><a-card :bordered="false" class="card"><div v-if="item"><div class="eyebrow">POINT LOG DETAIL</div><h1>{{item.remark||'积分变动'}}</h1><div class="points" :class="Number(item.changeVal)>=0?'plus':'minus'">{{Number(item.changeVal)>=0?'+':''}}{{item.changeVal}} 积分</div><a-descriptions bordered :column="1"><a-descriptions-item label="流水 ID">{{item.logId}}</a-descriptions-item><a-descriptions-item label="关联订单">{{item.refOrderNo||'—'}}</a-descriptions-item><a-descriptions-item label="时间">{{String(item.createTime||'').replace('T',' ')}}</a-descriptions-item><a-descriptions-item label="类型">{{item.changeType}}</a-descriptions-item></a-descriptions></div><a-empty v-else description="未找到积分流水"/></a-card></div></template>
<script setup>import {ref,onMounted} from 'vue';import {membershipApi} from '../api';const item=ref(null);onMounted(async()=>{try{const d=await membershipApi.my();const id=location.pathname.split('/').pop();item.value=(d?.pointsLog||[]).find(x=>String(x.logId)===String(id))||null}catch(e){}})</script>
<style scoped>.page{max-width:760px;margin:0 auto}.card{border-radius:22px;padding:10px}.eyebrow{font-size:11px;letter-spacing:.16em;color:var(--ll-primary)}h1{margin:6px 0 8px}.points{font-size:38px;font-weight:800;margin:14px 0 24px}.plus{color:#16835a}.minus{color:#9b2d20}</style>